using System;
using System.Linq;
using AICad.Contracts;
using Newtonsoft.Json.Linq;
namespace AICad.Application;
public sealed class LibraryManagementService(WorkspaceService workspace){
 void Exists(string kind,string id){LibraryCatalog.Kind(kind);if(!workspace.Store.Ids(kind).Contains(id))throw new CadException("NOT_FOUND",id);}
 public object State(string kind){LibraryCatalog.Kind(kind);if(kind=="layers"||kind=="blocks")return new{groups=workspace.Catalog.Groups(kind),items=Array.Empty<object>()};return new{groups=workspace.Catalog.Groups(kind),items=workspace.Store.Ids(kind).Where(id=>!workspace.Retired(kind,id)).Select(id=>{var m=workspace.Catalog.Label(kind,id);string original=kind=="skills"?workspace.Store.Skill(id).Name:workspace.Store.Template(id).Name;return new{Id=id,Name=m.Name==""?original:m.Name,m.GroupId,m.DeletedUtc,originalName=original};}).ToList()};}
 public object LayerState(string templateId){var t=workspace.Template(templateId);return new{templateId=t.Id,version=t.Version,groups=workspace.Catalog.Groups("layers"),items=t.Layers.Select(l=>new{Name=l.Name,GroupId=workspace.Catalog.Label("layers",Json.Hash(new[]{t.Id,l.Name})).GroupId}).ToArray()};}
 public object AssignLayers(JObject p){string id=p.Value<string>("templateId")??"";var t=workspace.Template(id);if(p.Value<string>("version")!=t.Version)throw new CadException("RESOURCE_CHANGED","Phiên bản thư viện đã đổi, tải lại trước khi phân nhóm layer.");var names=p["names"]?.ToObject<string[]>()??Array.Empty<string>();if(names.Length==0||names.Length>100||names.Distinct().Count()!=names.Length||names.Any(n=>!t.Layers.Any(l=>l.Name==n)))throw new CadException("INVALID_LAYER","Chọn các layer thuộc thư viện hiện tại.");workspace.Catalog.SetGroups("layers",names.Select(n=>Json.Hash(new[]{id,n})).ToList(),p.Value<string>("groupId")??"");return new{status="UPDATED",count=names.Length};}
 public object BlockState(string templateId){var t=workspace.Template(templateId);return new{templateId=t.Id,version=t.Version,groups=workspace.Catalog.Groups("blocks"),items=t.Blocks.Select(l=>new{Name=l.Id,GroupId=workspace.Catalog.Label("blocks",Json.Hash(new[]{t.Id,l.Id})).GroupId}).ToArray()};}
 public object AssignBlocks(JObject p){string id=p.Value<string>("templateId")??"";var t=workspace.Template(id);if(p.Value<string>("version")!=t.Version)throw new CadException("RESOURCE_CHANGED","Phiên bản thư viện đã đổi, tải lại trước khi phân nhóm block.");var names=p["names"]?.ToObject<string[]>()??Array.Empty<string>();if(names.Length==0||names.Length>1000||names.Distinct().Count()!=names.Length||names.Any(n=>!t.Blocks.Any(l=>l.Id==n)))throw new CadException("INVALID_BLOCK","Chọn các block thuộc thư viện hiện tại.");workspace.Catalog.SetGroups("blocks",names.Select(n=>Json.Hash(new[]{id,n})).ToList(),p.Value<string>("groupId")??"");return new{status="UPDATED",count=names.Length};}
 public object Update(JObject p){string kind=p.Value<string>("kind")??"",id=p.Value<string>("id")??"";Exists(kind,id);return workspace.Catalog.Update(kind,id,p.Value<string>("name")??"",p.Value<string>("groupId")??"");}
 public object Delete(JObject p,bool restore){string kind=p.Value<string>("kind")??"",id=p.Value<string>("id")??"";Exists(kind,id);return workspace.Catalog.Edit(()=>{if(!restore){var active=workspace.History().Where(r=>new[]{"READY","PREVIEW","DISPATCHED","UNKNOWN"}.Contains(r.Status)&&(kind=="skills"?r.Plan.SkillId==id:r.Plan.Template.Id==id)).ToList();if(active.Count>0)throw new CadException("RESOURCE_IN_USE","Còn "+active.Count+" kế hoạch đang chờ hoặc cần đối soát. Hoàn tất/hủy kế hoạch trước.");if(kind=="templates"){var consumers=workspace.TemplateConsumers(id).Where(s=>!workspace.Retired("skills",s)).ToList();if(consumers.Count>0)throw new CadException("DEPENDENCY_IMPACT","Thư viện đang được Skill sử dụng: "+string.Join(", ",consumers)+". Đổi thư viện cho Skill hoặc xóa Skill trước.");}}else if(kind=="skills"){var s=workspace.Store.Skill(id);workspace.Catalog.Available("templates",s.TemplateId);workspace.ValidateSkill(s);}return workspace.Catalog.Trash(kind,id,!restore);});}
 public object Group(JObject p){string kind=p.Value<string>("kind")??"";if(p.Value<string>("action")=="remove"){workspace.Catalog.RemoveGroup(kind,p.Value<string>("id")??"");return new{status="REMOVED"};}return workspace.Catalog.Group(kind,p.Value<string>("id")??"",p.Value<string>("name")??"",p.Value<string>("parentId"));}
}
